1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import { connectionTarget, serverRootPassword } from "../lib/sftp";
4	import { INSTALLABLE_FAMILIES, RESOLVABLE_SOURCES } from "../lib/mod-install-support";
5	import { controlSpec } from "../lib/game-control";
6	import { Client, type ClientChannel, type SFTPWrapper } from "ssh2";
7	import type { Job } from "@prisma/client";
8	
9	/**
10	 * GAME_MOD_SYNC handler — reconcile a game server's installed mods to the desired
11	 * state recorded in `ServerMod` rows:
12	 *   - status INSTALLING → fetch + install the mod, then INSTALLED (or FAILED)
13	 *   - status REMOVING   → remove the mod, then delete the row (or FAILED)
14	 *
15	 * Wire into worker/index.ts handlers:  GAME_MOD_SYNC: gameModSync,
16	 *
17	 * THREE PATHS, mirroring game-config's honesty guard so we never tell a customer a
18	 * mod is installed when nothing was written to their server:
19	 *  - SANDBOX: simulate (flip INSTALLING→INSTALLED, REMOVING→REMOVED). Dev only.
20	 *  - REAL (ENABLE_REAL_GAMEMODS=1, not sandbox): install/remove over SSH via the
21	 *    per-source adapter. Where an adapter isn't implemented yet, the mod is marked
22	 *    FAILED with a clear reason — never silently "INSTALLED".
23	 *  - Neither (production, flag off): mark the queued changes FAILED with a plain
24	 *    message. A change we did NOT apply is a failure and must say so.
25	 */
26	
27	const REAL_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMEMODS === "1";
28	
29	async function notify(userId: string, title: string, body?: string, href?: string) {
30	  try {
31	    await db.notification.create({ data: { userId, title, body, href } });
32	  } catch (e) {
33	    console.error("[game-mods] notify failed", e);
34	  }
35	}
36	
37	export async function gameModSync(job: Job): Promise<void> {
38	  const serverId = job.serverId;
39	  if (!serverId) throw new Error("game mod sync: job has no serverId");
40	
41	  const server = await db.server.findUnique({
42	    where: { id: serverId },
43	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
44	  });
45	  if (!server) throw new Error(`Server ${serverId} not found`);
46	
47	  const pending = await db.serverMod.findMany({
48	    where: { serverId, status: { in: ["INSTALLING", "REMOVING"] } },
49	    include: { mod: true },
50	  });
51	  if (pending.length === 0) return;
52	
53	  const installedNames: string[] = [];
54	  const removedNames: string[] = [];
55	  const failedNames: string[] = [];
56	
57	  for (const sm of pending) {
58	    const removing = sm.status === "REMOVING";
59	    try {
60	      if (SANDBOX) {
61	        // Dev simulation — no VM mutation.
62	        if (removing) {
63	          await db.serverMod.delete({ where: { id: sm.id } });
64	          removedNames.push(sm.mod.name);
65	        } else {
66	          await db.serverMod.update({ where: { id: sm.id }, data: { status: "INSTALLED", error: null } });
67	          installedNames.push(sm.mod.name);
68	        }
69	        continue;
70	      }
71	
72	      if (!REAL_ENABLED) {
73	        // Honest failure: nothing was applied. Do NOT report success.
74	        await db.serverMod.update({
75	          where: { id: sm.id },
76	          data: {
77	            status: "FAILED",
78	            error:
79	              "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified.",
80	          },
81	        });
82	        failedNames.push(sm.mod.name);
83	        continue;
84	      }
85	
86	      // REAL path — install/remove over SSH via the per-source adapter.
87	      const modRow: ModRowFull = {
88	        gameFamily: sm.mod.gameFamily,
89	        source: sm.mod.source,
90	        sourceId: sm.mod.sourceId,
91	        slug: sm.mod.slug,
92	        name: sm.mod.name,
93	        url: sm.mod.url,
94	        variant: server.gameVariant ?? null,
95	        appliesTo: sm.mod.appliesToVariant ?? null,
96	      };
97	      const result =
98	        sm.mod.source === "steam_workshop"
99	          ? await workshopSync(server, sm.mod.gameFamily, serverId)
100	          : removing
101	          ? await removeModReal(server, modRow)
102	          : await installModReal(server, modRow);
103	
104	      if (result.ok) {
105	        if (removing) {
106	          await db.serverMod.delete({ where: { id: sm.id } });
107	          removedNames.push(sm.mod.name);
108	        } else {
109	          await db.serverMod.update({
110	            where: { id: sm.id },
111	            data: { status: "INSTALLED", version: result.version ?? null, error: null },
112	          });
113	          installedNames.push(sm.mod.name);
114	        }
115	      } else {
116	        await db.serverMod.update({
117	          where: { id: sm.id },
118	          data: { status: removing ? "INSTALLED" : "FAILED", error: result.error ?? "install failed" },
119	        });
120	        failedNames.push(sm.mod.name);
121	      }
122	    } catch (e) {
123	      const msg = e instanceof Error ? e.message : String(e);
124	      console.error(`[game-mods] ${removing ? "remove" : "install"} failed for ${sm.mod.slug}:`, e);
125	      await db.serverMod.update({
126	        where: { id: sm.id },
127	        // A failed removal stays INSTALLED (it's still there); a failed install is FAILED.
128	        data: { status: removing ? "INSTALLED" : "FAILED", error: msg },
129	      });
130	      failedNames.push(sm.mod.name);
131	    }
132	  }
133	
134	  // One summary notification for the batch.
135	  const parts: string[] = [];
136	  if (installedNames.length) parts.push(`installed ${installedNames.join(", ")}`);
137	  if (removedNames.length) parts.push(`removed ${removedNames.join(", ")}`);
138	  if (failedNames.length) parts.push(`could not apply ${failedNames.join(", ")}`);
139	  const anyOk = installedNames.length > 0 || removedNames.length > 0;
140	  const allFailed = !anyOk && failedNames.length > 0;
141	
142	  await notify(
143	    server.userId,
144	    allFailed ? `Mod changes failed on ${server.hostname}` : `Mods updated on ${server.hostname}`,
145	    parts.length ? `${parts.join("; ")}.` : "No changes were made.",
146	    `/dashboard/servers/${server.id}?tab=mods`
147	  );
148	}
149	
150	// ===========================================================================
151	// Real install/remove — per-source adapters over SSH.
152	//
153	// Approach: the worker resolves a DIRECT download URL from the source's API, then
154	// SSHes into the game VM and has the VM itself `curl` the file into the game's
155	// plugin/mod directory (deterministic filename, so uninstall is a plain rm — no
156	// per-install state to track). Sources that need auth or per-repo handling
157	// (GitHub release zips, Nexus, CurseForge key, Codefling paid) soft-fail with a
158	// clear "install manually from <url>" note rather than faking success.
159	//
160	// Supported today: modrinth + spigotmc (Minecraft), umod (Rust), thunderstore
161	// (Valheim) — which fully covers those three games' catalogs. `steam_workshop`
162	// mods use a completely different mechanism — see the big Steam Workshop
163	// section near the end of this file — and never go through planTarget/
164	// resolveUrl/modDirShell below at all.
165	// ===========================================================================
166	
167	type ModResult = { ok: boolean; version?: string; error?: string };
168	type ModRow = {
169	  gameFamily: string;
170	  source: string;
171	  sourceId: string | null;
172	  slug: string;
173	  name: string;
174	  url: string | null;
175	};
176	type SshServer = {
177	  id: string;
178	  rootPassword: string | null;
179	  rootPasswordEnc?: string | null;
180	  sshPort: number | null;
181	  dedicatedIp?: { address: string } | null;
182	  node?: { publicIp: string } | null;
183	};
184	
185	const CONNECT_TIMEOUT_MS = 15_000;
186	const EXEC_TIMEOUT_MS = 200_000; // downloads can be large
187	
188	/** PascalCase a mod name for an Oxide/Carbon .cs filename (class-name convention). */
189	function pascal(name: string): string {
190	  const p = name.replace(/[^a-zA-Z0-9]+/g, " ").trim().split(/\s+/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
191	  return p || "Plugin";
192	}
193	
194	/** Deterministic on-disk target for a mod, or null if its source isn't installable. */
195	function planTarget(mod: ModRow): { kind: "jar" | "cs" | "zip"; file?: string; folder?: string } | null {
196	  switch (mod.source) {
197	    case "modrinth":
198	    case "spigotmc":
199	      return { kind: "jar", file: `nxeon-${mod.slug}.jar` };
200	    case "umod":
201	      return { kind: "cs", file: `${pascal(mod.name)}.cs` };
202	    case "thunderstore":
203	      return { kind: "zip", folder: `nxeon-${mod.slug}` };
204	    case "github":
205	      // Same "zip-of-a-folder" shape as thunderstore — a reasonable generic
206	      // default for a GitHub release asset, but untested against a real CS2
207	      // plugin's actual archive layout (addons/ layout vs. a bare .dll/.so vs.
208	      // a source tarball all differ per repo). Harmless today: no family in
209	      // INSTALLABLE_FAMILIES is github-sourced (see mod-install-support.ts),
210	      // so modDirShell always returns null first and this never actually runs
211	      // an install. Revisit this specific shape when a family is wired up.
212	      return { kind: "zip", folder: `nxeon-${mod.slug}` };
213	    default:
214	      return null; // nexus / curseforge / codefling / hangar — manual
215	  }
216	}
217	
218	/** Resolve a direct download URL from the source's API (worker-side). */
219	async function resolveUrl(mod: ModRowFull): Promise<string | null> {
220	  const id = mod.sourceId ?? "";
221	  try {
222	    switch (mod.source) {
223	      case "umod":
224	        return `https://umod.org/plugins/${id}.cs`;
225	      case "spigotmc":
226	        return `https://api.spiget.org/v2/resources/${id}/download`;
227	      case "modrinth": {
228	        const loader = modrinthLoader(mod);
229	        const q = loader ? `?loaders=["${loader}"]` : "";
230	        const res = await fetch(`https://api.modrinth.com/v2/project/${id}/version${q}`, {
231	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
232	        });
233	        if (!res.ok) return null;
234	        const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
235	        const v = versions[0];
236	        if (!v) return null;
237	        return (v.files.find((f) => f.primary) ?? v.files[0])?.url ?? null;
238	      }
239	      case "thunderstore": {
240	        const [author, ...rest] = id.split("-");
241	        if (!rest.length) return null;
242	        const res = await fetch(`https://thunderstore.io/api/experimental/package/${author}/${rest.join("-")}/`, {
243	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
244	        });
245	        if (!res.ok) return null;
246	        const pkg = (await res.json()) as { latest?: { download_url?: string } };
247	        return pkg.latest?.download_url ?? null;
248	      }
249	      case "github": {
250	        // id is "owner/repo" (scripts/import-github-catalog.ts's sourceId
251	        // convention, matching prisma/seed-gamemods.ts's pre-existing CS2
252	        // rows). Resolved fresh at install time, same as modrinth above —
253	        // nothing about the release is cached on the GameMod row, so a mod
254	        // author cutting a new release just works with no re-import needed.
255	        const headers: Record<string, string> = { "User-Agent": "Nxeon/1.0 (mod-manager)", Accept: "application/vnd.github+json" };
256	        if (process.env.GITHUB_TOKEN) headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
257	        const res = await fetch(`https://api.github.com/repos/${id}/releases/latest`, { headers });
258	        if (!res.ok) return null; // no releases yet, repo renamed/gone, or rate-limited
259	        const release = (await res.json()) as { assets?: Array<{ browser_download_url: string; name: string }> };
260	        const assets = release.assets ?? [];
261	        if (assets.length === 0) return null;
262	        // Prefer a real packaged archive over a loose source-only asset when both exist.
263	        const archive = assets.find((a) => /\.(zip|tar\.gz|tgz)$/i.test(a.name));
264	        return (archive ?? assets[0]).browser_download_url;
265	      }
266	      default:
267	        return null;
268	    }
269	  } catch (e) {
270	    console.error(`[game-mods] resolveUrl(${mod.source}/${id}) failed`, e);
271	    return null;
272	  }
273	}
274	
275	function modrinthLoader(mod: ModRowFull): string | null {
276	  // Prefer the mod's own loader target; fall back to the server's variant.
277	  const key = mod.appliesTo ?? mod.variant ?? "";
278	  const map: Record<string, string> = {
279	    paper: "paper", spigot: "spigot", purpur: "purpur", bukkit: "bukkit",
280	    fabric: "fabric", forge: "forge", neoforge: "neoforge", quilt: "quilt",
281	  };
282	  return map[key] ?? null;
283	}
284	
285	/** Shell snippet that echoes (creating if needed) the mod/plugin dir for family+variant. */
286	/* The shared set in lib/mod-install-support.ts is what the PANEL uses to decide
287	   whether to draw an Install button at all. If this switch ever grows a case
288	   that isn't in that set the button never appears, and if the set grows a
289	   family this switch doesn't handle the button appears and fails — which is the
290	   bug that module was written to end. Fail loudly here rather than let them
291	   drift apart silently. */
292	function modDirShell(family: string, variant: string | null): string | null {
293	  if (!INSTALLABLE_FAMILIES.has(family)) return null;
294	  switch (family) {
295	    case "minecraft": {
296	      const modded = variant && ["fabric", "forge", "neoforge", "quilt"].includes(variant);
297	      const sub = modded ? "mods" : "plugins";
298	      return `root=$(find /opt /srv /home /root -maxdepth 6 -name server.properties -printf '%h\\n' 2>/dev/null | head -1); [ -n "$root" ] && { mkdir -p "$root/${sub}"; echo "$root/${sub}"; }`;
299	    }
300	    case "rust":
301	      return `d=$(find /opt /srv /home -maxdepth 9 -type d \\( -name oxide -o -name carbon \\) 2>/dev/null | head -1); [ -n "$d" ] && { mkdir -p "$d/plugins"; echo "$d/plugins"; }`;
302	    // Was a case-sensitive `find -name BepInEx` — always a no-op even with
303	    // BepInEx installed, since lloesche/valheim-server's own real directory is
304	    // lowercase `bepinex` (confirmed against its README). Use the documented,
305	    // fixed path directly instead of searching for it: `/config` is the
306	    // catalog's own `-v /opt/valheim/config:/config` mount, and the image
307	    // itself watches `/config/bepinex/plugins` for user-added plugins and
308	    // copies them into the real BepInEx plugin dir on boot — this is the
309	    // customer-facing "drop mods here" folder by design, not an internal path.
310	    case "valheim":
311	      return `d=/opt/valheim/config/bepinex/plugins; [ -d /opt/valheim/config/bepinex ] && { mkdir -p "$d"; echo "$d"; }`;
312	    default:
313	      return null;
314	  }
315	}
316	
317	const shq = (s: string) => s.replace(/'/g, "'\\''");
318	
319	async function installModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
320	  const target = planTarget(mod);
321	  if (!target) {
322	    return { ok: false, error: `Auto-install isn't available for ${mod.source} mods yet — install manually${mod.url ? ` from ${mod.url}` : ""}.` };
323	  }
324	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
325	  if (!dirShell) {
326	    return { ok: false, error: `Auto-install isn't wired for this game yet.` };
327	  }
328	  if (!RESOLVABLE_SOURCES.has(mod.source)) {
329	    return { ok: false, error: `We can't fetch downloads from ${mod.source} — install this one by hand in Files.` };
330	  }
331	  const url = await resolveUrl(mod);
332	  if (!url) return { ok: false, error: "Could not resolve a download for this mod (it may have moved)." };
333	
334	  let cmd: string;
335	  if (target.kind === "zip") {
336	    cmd =
337	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
338	      `tmp=$(mktemp -d); if curl -fsSL --max-time 180 -o "$tmp/m.zip" '${shq(url)}'; then ` +
339	      `rm -rf "$dir/${target.folder}"; mkdir -p "$dir/${target.folder}"; ` +
340	      `unzip -oq "$tmp/m.zip" -d "$dir/${target.folder}" && echo OK || echo UNZIP; rm -rf "$tmp"; else echo FAIL; fi`;
341	  } else {
342	    cmd =
343	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
344	      `if curl -fsSL --max-time 180 -o "$dir/${target.file}" '${shq(url)}'; then echo OK; else echo FAIL; fi`;
345	  }
346	
347	  const out = await withSsh(server, (conn) => execRemote(conn, cmd));
348	  const s = out.stdout.trim();
349	  if (s.endsWith("OK")) return { ok: true };
350	  if (s.includes("NODIR")) return { ok: false, error: "Couldn't find the game's mod folder — is the server fully set up?" };
351	  if (s.includes("UNZIP")) return { ok: false, error: "Downloaded the mod but couldn't unpack it (unzip missing?)." };
352	  return { ok: false, error: "Download failed on the server." };
353	}
354	
355	async function removeModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
356	  const target = planTarget(mod);
357	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
358	  if (!target || !dirShell) return { ok: true }; // nothing we placed → nothing to remove
359	  const rm =
360	    target.kind === "zip"
361	      ? `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -rf "$dir/${target.folder}"; echo OK`
362	      : `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -f "$dir/${target.file}"; echo OK`;
363	  await withSsh(server, (conn) => execRemote(conn, rm));
364	  return { ok: true };
365	}
366	
367	// --- SSH transport (root@VM, password from the same source as the file manager) ---
368	
369	type ModRowFull = ModRow & { variant: string | null; appliesTo: string | null };
370	
371	function withSsh<T>(server: SshServer, fn: (conn: Client) => Promise<T>): Promise<T> {
372	  return new Promise((resolve, reject) => {
373	    const t = connectionTarget(server as any);
374	    if (!t) return reject(new Error("server is not reachable yet"));
375	    const password = serverRootPassword(server as any);
376	    if (!password) return reject(new Error("server has no root password set"));
377	    const conn = new Client();
378	    let settled = false;
379	    const finish = (err: Error | null, val?: T) => {
380	      if (settled) return;
381	      settled = true;
382	      try { conn.end(); } catch { /* best-effort */ }
383	      err ? reject(err) : resolve(val as T);
384	    };
385	    conn.on("ready", () => {
386	      fn(conn).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
387	    });
388	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
389	    conn.connect({ host: t.host, port: t.port, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
390	  });
391	}
392	
393	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
394	  return new Promise((resolve, reject) => {
395	    conn.exec(cmd, (err, stream: ClientChannel) => {
396	      if (err) return reject(err);
397	      let stdout = "";
398	      let stderr = "";
399	      const timer = setTimeout(() => { try { stream.close(); } catch { /* ignore */ } }, EXEC_TIMEOUT_MS);
400	      stream
401	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, stdout, stderr }); })
402	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
403	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
404	    });
405	  });
406	}
407	
408	// ===========================================================================
409	// Steam Workshop — pure config-write installs (NxLabs Phase 3, 2026-09-20).
410	//
411	// Nxeon NEVER downloads or mirrors the actual Workshop file here. For every
412	// family below, one of two things is true, confirmed against each game's own
413	// documentation (see docs/DOCUMENTATION.md's 2026-09-20 entry for the full
414	// citations and per-family confidence level — some of this is authoritative,
415	// a couple are best-available community evidence flagged as such):
416	//
417	//   (a) the dedicated server binary itself fetches Workshop content on boot
418	//       once its ID is present in the right env var / config file / launch
419	//       arg — ark, dst, squad, soulmask, unturned, projectzomboid, tf2 all
420	//       work this way, confirmed against either the game's own wiki or (for
421	//       the Docker-run families this platform actually provisions) the exact
422	//       image's own documented env vars; or
423	//   (b) the dedicated binary does NOT fetch Workshop content itself, so we
424	//       run `steamcmd` — Valve's own tool — ONCE inside the customer's own
425	//       container to pull the item from Steam's CDN, exactly like a real
426	//       Steam client subscribing would (l4d2, empyrion, and — only to learn
427	//       Project Zomboid's separate internal mod-id string, never to keep the
428	//       downloaded content — projectzomboid).
429	//
430	// Every apply function here RECOMPUTES the full desired Workshop-id list from
431	// this server's currently INSTALLED/INSTALLING `ServerMod` rows (see
432	// `desiredWorkshopMods`) and writes/executes that whole set, never a single
433	// mod in isolation — required because most of these mechanisms are a single
434	// field holding ALL of a server's Workshop ids (an env var, a JSON array, an
435	// ini list), so "install mod B" and "remove mod A" are really both just
436	// "reapply the current desired set."
437	// ===========================================================================
438	
439	/** Steam Workshop items filed under the game's own client appid (verified
440	 *  live against IPublishedFileService/QueryFiles/v1 — see
441	 *  scripts/import-steamworkshop-catalog.ts's header for how these were
442	 *  confirmed, not guessed). */
443	const WORKSHOP_APPID: Record<string, number> = {
444	  ark: 346110,
445	  unturned: 304930,
446	  dst: 322330,
447	  squad: 393380,
448	  empyrion: 383120,
449	  soulmask: 2646460,
450	  projectzomboid: 108600,
451	  tf2: 440,
452	  l4d2: 550,
453	};
454	
455	/** All `ServerMod` rows this server currently wants active for a family's
456	 *  Workshop source — the row for the mod mid-install/removal is already
457	 *  reflected correctly here since its own status (INSTALLING/REMOVING) is
458	 *  what this query filters on. */
459	async function desiredWorkshopMods(
460	  serverId: string,
461	  gameFamily: string
462	): Promise<{ sourceId: string; modStringId: string | null; gameModId: string }[]> {
463	  const rows = await db.serverMod.findMany({
464	    where: { serverId, status: { in: ["INSTALLED", "INSTALLING"] }, mod: { gameFamily, source: "steam_workshop" } },
465	    include: { mod: true },
466	  });
467	  return rows
468	    .filter((r) => !!r.mod.sourceId)
469	    .map((r) => ({ sourceId: r.mod.sourceId as string, modStringId: r.mod.modStringId, gameModId: r.modId }));
470	}
471	
472	/** Dispatch: recompute this server's desired Workshop-id set for `gameFamily`
473	 *  and apply it via that family's real, documented mechanism. */
474	async function workshopSync(server: SshServer, gameFamily: string, serverId: string): Promise<ModResult> {
475	  const desired = await desiredWorkshopMods(serverId, gameFamily);
