501	// --- SFTP transport (same auth as withSsh, adds an SFTP channel for file writes) ---
502	
503	function withSftp<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
504	  return new Promise((resolve, reject) => {
505	    const t = connectionTarget(server as any);
506	    if (!t) return reject(new Error("server is not reachable yet"));
507	    const password = serverRootPassword(server as any);
508	    if (!password) return reject(new Error("server has no root password set"));
509	    const conn = new Client();
510	    let settled = false;
511	    const finish = (err: Error | null, val?: T) => {
512	      if (settled) return;
513	      settled = true;
514	      try { conn.end(); } catch { /* best-effort */ }
515	      err ? reject(err) : resolve(val as T);
516	    };
517	    conn.on("ready", () => {
518	      conn.sftp((err, sftp) => {
519	        if (err) return finish(err);
520	        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
521	      });
522	    });
523	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
524	    conn.connect({ host: t.host, port: t.port, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
525	  });
526	}
