823	function stripMarkedBlock(content: string, start: string, end: string): string {
824	  const s = content.indexOf(start);
825	  if (s < 0) return content;
826	  const e = content.indexOf(end, s);
827	  if (e < 0) return content;
828	  return content.slice(0, s) + content.slice(e + end.length);
