884	async function applyL4d2Workshop(server: SshServer, ids: string[]): Promise<ModResult> {
885	  return withSftp(server, async (conn, sftp) => {
886	    for (const id of ids) {
887	      const check = await execRemote(conn, `[ -f '/opt/l4d2/addons/${shq(id)}.vpk' ] && echo YES`);
888	      if (check.stdout.trim() === "YES") continue; // already fetched
889	
890	      const tmp = `/tmp/nxw-${id}`;
891	      await execRemote(
892	        conn,
893	        `docker exec l4d2 steamcmd +login anonymous +force_install_dir '${shq(tmp)}' +workshop_download_item ${L4D2_APPID} ${shq(id)} +quit >/dev/null 2>&1`
894	      );
895	      const found = await execRemote(conn, `docker exec l4d2 sh -c "find '${shq(tmp)}' -iname '*.vpk' 2>/dev/null | head -1"`);
896	      const vpkPath = found.stdout.trim();
897	      if (vpkPath) {
898	        await execRemote(conn, `docker exec l4d2 cp '${shq(vpkPath)}' /addons/${shq(id)}.vpk`);
899	      }
900	      await execRemote(conn, `docker exec l4d2 rm -rf '${shq(tmp)}' >/dev/null 2>&1`);
901	
902	      const confirm = await execRemote(conn, `[ -f '/opt/l4d2/addons/${shq(id)}.vpk' ] && echo YES`);
903	      if (confirm.stdout.trim() !== "YES") {
904	        return { ok: false, error: `Could not fetch Steam Workshop item ${id} for this server — it may be private, removed, or not an L4D2 addon.` };
905	      }
906	    }
907	
908	    // Drop vpks for anything no longer desired.
909	    const present = await execRemote(conn, `ls /opt/l4d2/addons/*.vpk 2>/dev/null`);
910	    for (const line of present.stdout.split(/\r?\n/)) {
911	      const base = line.trim().split("/").pop();
912	      const id = base?.replace(/\.vpk$/, "");
913	      if (id && !ids.includes(id)) await execRemote(conn, `rm -f '/opt/l4d2/addons/${shq(id)}.vpk'`);
914	    }
915	
916	    const addonlist = ids.map((id) => `addons/${id}.vpk`).join("\n") + (ids.length ? "\n" : "");
917	    await sftpWrite(sftp, "/opt/l4d2/addons/addonlist.txt", addonlist);
918	    return { ok: true };
919	  });
920	}
921	
922	/**
923	 * Empyrion — NOT pure config-write, and NOT a growing list: the official
924	 * wiki's `dedicated.yaml` reference has exactly one relevant key,
925	 * `CustomScenario`, and it takes a SINGLE local folder name, not a Workshop
926	 * id or a list. So unlike every other family here, Empyrion can only have
927	 * ONE active Workshop scenario at a time — attempting a second install while
928	 * one is already active is refused rather than silently replacing it.
929	 *
930	 * Mechanism: `steamcmd workshop_download_item` (Valve's own tool, run inside
931	 * the customer's own container — bitr/empyrion-server documents a generic
932	 * `STEAMCMD=` passthrough env var for exactly this kind of one-off command)
933	 * fetches the scenario into the container's own workshop content cache; we
934	 * then copy it into `Content/Scenarios/` under a fixed name and point
935	 * `dedicated.yaml`'s `CustomScenario` at it.
936	 *
937	 * CONFIDENCE NOTE: the exact internal path layout under this image's mounted
938	 * volume (`/opt/empyrion` on the host, `/home/user/Steam` in the container)
939	 * is discovered at run time via `find` rather than hardcoded, because no
940	 * official source documents it precisely — if `dedicated.yaml` or
941	 * `Content/Scenarios` can't be located, this fails honestly instead of
942	 * guessing a path and silently writing nothing (or writing to the wrong
943	 * place).
944	 */
945	const EMPYRION_APPID = WORKSHOP_APPID.empyrion;
946	
947	async function patchEmpyrionScenario(conn: Client, sftp: SFTPWrapper, root: string, scenarioName: string | null): Promise<ModResult> {
948	  const found = await execRemote(conn, `find '${shq(root)}' -maxdepth 8 -type f -iname 'dedicated.yaml' 2>/dev/null | head -1`);
949	  const path = found.stdout.trim();
950	  if (!path) return { ok: false, error: "Could not locate dedicated.yaml on this server — nothing was changed." };
951	  const existing = await sftpRead(sftp, path);
952	  if (existing == null) return { ok: false, error: "dedicated.yaml disappeared — nothing was changed." };
953	  if (!/^\s*CustomScenario\s*:/m.test(existing)) {
954	    return { ok: false, error: "Could not find a CustomScenario key in dedicated.yaml — set it manually to activate this scenario." };
955	  }
956	  const line = scenarioName ? `    CustomScenario: '${scenarioName}'` : `    CustomScenario: ''`;
957	  const updated = existing.replace(/^\s*CustomScenario\s*:.*$/m, line);
958	  await sftpWrite(sftp, path, updated);
959	  return { ok: true };
960	}
961	
962	async function applyEmpyrionWorkshop(server: SshServer, ids: string[]): Promise<ModResult> {
963	  if (ids.length > 1) {
964	    return {
965	      ok: false,
966	      error: "Empyrion's dedicated server can only run one active Workshop scenario at a time — remove the current one before adding another.",
967	    };
968	  }
969	  return withSftp(server, async (conn, sftp) => {
970	    const root = "/opt/empyrion";
971	    if (ids.length === 0) {
972	      return patchEmpyrionScenario(conn, sftp, root, null);
973	    }
974	    const id = ids[0];
975	    await execRemote(
976	      conn,
977	      `docker exec empyrion steamcmd +login anonymous +force_install_dir /home/user/Steam +workshop_download_item ${EMPYRION_APPID} ${shq(id)} +quit >/dev/null 2>&1`
978	    );
979	    const found = await execRemote(
980	      conn,
981	      `find '${shq(root)}/steamapps/workshop/content/${EMPYRION_APPID}/${shq(id)}' -maxdepth 1 -type d 2>/dev/null | head -1`
982	    );
983	    const contentDir = found.stdout.trim();
984	    if (!contentDir) {
985	      return { ok: false, error: `Could not fetch Steam Workshop scenario ${id} — it may be private, removed, or not an Empyrion scenario.` };
986	    }
987	    const scenariosDirRes = await execRemote(conn, `find '${shq(root)}' -maxdepth 8 -type d -path '*/Content/Scenarios' 2>/dev/null | head -1`);
988	    const scenariosDir = scenariosDirRes.stdout.trim();
989	    if (!scenariosDir) {
990	      return { ok: false, error: "Could not locate this server's Content/Scenarios directory — nothing was changed." };
991	    }
992	    const scenarioName = `nxw-${id}`;
993	    await execRemote(
994	      conn,
995	      `rm -rf '${shq(scenariosDir)}/${shq(scenarioName)}' && cp -r '${shq(contentDir)}' '${shq(scenariosDir)}/${shq(scenarioName)}'`
996	    );
997	    return patchEmpyrionScenario(conn, sftp, root, scenarioName);
998	  });
999	}
