266	// ── GitHub REST client: real rate-limit tracking, graceful stop (not a long sleep) ──
267	class BudgetExhausted extends Error {}
268	
269	class GhClient {
270	  private coreRemaining = Infinity;
271	  private coreResetAt = 0;
272	  constructor(private safetyMargin: number) {}
273	
274	  private headers(): Record<string, string> {
275	    const h: Record<string, string> = { "User-Agent": UA, Accept: "application/vnd.github+json" };
276	    if (GITHUB_TOKEN) h.Authorization = `Bearer ${GITHUB_TOKEN}`;
277	    return h;
278	  }
279	
280	  /** Throws BudgetExhausted rather than firing a request we already know will 403/429. */
281	  private checkBudget() {
282	    if (this.coreRemaining <= this.safetyMargin) {
283	      const waitS = Math.max(0, Math.round((this.coreResetAt - Date.now()) / 1000));
284	      throw new BudgetExhausted(
285	        `core rate-limit budget exhausted (remaining=${this.coreRemaining}, resets in ~${waitS}s)`
286	      );
287	    }
288	  }
289	
290	  private track(res: Response) {
291	    const remaining = res.headers.get("x-ratelimit-remaining");
292	    const reset = res.headers.get("x-ratelimit-reset");
293	    if (remaining !== null) this.coreRemaining = Number(remaining);
294	    if (reset !== null) this.coreResetAt = Number(reset) * 1000;
295	  }
296	
297	  /** A real, budget-tracked GET against the GitHub REST API (core quota). */
298	  async core(path: string): Promise<Response | null> {
299	    this.checkBudget();
300	    const res = await fetch(`${API}${path}`, { headers: this.headers() });
301	    this.track(res);
302	    if (res.status === 403 || res.status === 429) {
303	      // Secondary/abuse limiter or we raced past the header check — stop
304	      // rather than sleep out an unknown, possibly long, cooldown.
305	      throw new BudgetExhausted(`GitHub returned ${res.status} on ${path} — stopping rather than sleeping it out`);
306	    }
307	    return res;
308	  }
309	
310	  /** Search quota is separate (10/min unauth) — not tracked against coreRemaining. */
