341	function classifyLicense(license: GhLicense): { raw: string | null; permissive: boolean } {
342	  if (!license) return { raw: null, permissive: false };
343	  const spdx = license.spdx_id;
344	  if (spdx && spdx !== "NOASSERTION" && PERMISSIVE_SPDX.has(spdx)) {
345	    return { raw: spdx, permissive: true };
346	  }
347	  // Never claim permissive for NOASSERTION/"other"/anything off the allowlist —
348	  // still store the real string GitHub reported.
349	  return { raw: (spdx && spdx !== "NOASSERTION" ? spdx : null) ?? license.name ?? "NOASSERTION", permissive: false };
