352	function passesQualityGate(repo: GhRepo): { ok: true } | { ok: false; reason: string } {
353	  const desc = (repo.description ?? "").trim();
354	  if (desc.length < MIN_DESCRIPTION_LEN) return { ok: false, reason: `no real description (len=${desc.length})` };
355	  if (repo.archived) return { ok: false, reason: "archived" };
356	  const ageDays = (Date.now() - new Date(repo.pushed_at).getTime()) / 86_400_000;
357	  if (ageDays > MAX_STALE_DAYS) return { ok: false, reason: `stale (last push ${Math.round(ageDays)}d ago)` };
358	  return { ok: true };
