374	async function fetchCuratedRepos(curated: CuratedList): Promise<Map<string, { section: string; stars?: number }>> {
375	  const out = new Map<string, { section: string; stars?: number }>();
376	  const res = await fetch(curated.url, { headers: { "User-Agent": UA } });
377	  if (!res.ok) {
378	    console.warn(`  [curated] fetch failed (${res.status}) for ${curated.url} — continuing without it`);
379	    return out;
380	  }
381	  const text = await res.text();
382	  const lines = text.split("\n");
383	  let section: string | null = null;
384	  let pendingStars: number | undefined;
385	  for (const line of lines) {
386	    const h = line.match(/^##\s+(.+?)\s*$/);
387	    if (h) {
388	      section = h[1].trim();
389	      continue;
390	    }
391	    if (!section || !curated.sections.includes(section)) continue;
392	    const starMatch = line.match(/⭐\s*([\d,]+)/);
393	    if (starMatch) pendingStars = Number(starMatch[1].replace(/,/g, ""));
394	    const repoMatch = line.match(/github\.com\/([\w.-]+\/[\w.-]+)\)/);
395	    if (repoMatch) {
396	      const fullName = repoMatch[1].replace(/\.git$/, "");
397	      out.set(fullName.toLowerCase(), { section, stars: pendingStars });
398	      pendingStars = undefined;
399	    }
400	  }
401	  return out;
402	}
