// ===========================================================================
// Terraria (TShock) — place a plugin .dll, restart, PROVE it loaded, or undo.
//
// Every other file-drop family above ends at "the file is in the folder".
// That is not enough here, for two reasons verified against a real running
// `ryshe/terraria` container (TShock 6.1.0.0 / TSAPI 2.1 / Terraria 1.4.5.6,
// 2026-09-30 — see docs/DOCUMENTATION.md's entry of that date):
//
//  1. TShock only loads plugins at startup. A file dropped into a running
//     server does nothing until the next restart, so "installed" without a
//     restart would be a claim nothing had checked yet.
//  2. A plugin that fails to load or throws in Initialize() does not just
//     skip itself: TSAPI logs "Startup aborted due to an exception in the
//     Server API initialization" and stops initializing plugins — observed
//     live, the world still comes up and logs "Server started", so the port
//     answers while TShock's own protections/commands may never have been
//     wired up. A catalogue entry built for another TShock version (or one
//     that hardcodes a path this image doesn't have — also observed live)
//     would otherwise sit there as a time bomb for the customer's next
//     restart.
//
// So an install here = download → check it's a PE file → restart the game's
// own systemd unit → read the new run's log → INSTALLED only if TShock logged
// a NEW "Plugin X vY (by Z) initiated." line and nothing aborted/threw that
// the previous run didn't; anything else is rolled back (file removed or the
// previous version restored, server restarted again) and reported FAILED
// with TShock's own reason.
//
// WHERE the file goes: not /tshock/ServerPlugins. That directory is an
// anonymous Docker VOLUME in this image holding TShock's OWN core
// (TShockAPI.dll — TShock is itself loaded as a plugin), seeded from the
// image and re-copied by the image's bootstrap.sh only when the folder is
// completely empty. Bind-mounting a host dir over it was tested live: an empty
// dir does get re-seeded, but a non-empty dir missing TShockAPI.dll boots with
// no TShock at all ("Could not load file or assembly 'TShockAPI'" → startup
// aborted), and a host copy of TShockAPI would go stale against any newer
// image. Instead the setupScript bind-mounts a SEPARATE host dir at
// TERRARIA_PLUGIN_MOUNT and passes TSAPI's own `-additionalplugins` flag
// (confirmed present in this build's TerrariaServer.dll) so TShock also loads
// *.dll from there — the image's core plugin volume is never touched.
//
// The whole sequence runs as ONE detached script on the VM (`runDetached`),
// polled over short SSH sessions, so a dropped SSH connection mid-restart
// can't kill it halfway between "file placed" and "verified or rolled back".
// ===========================================================================

/** Docker container name AND systemd unit name for Terraria — the catalog's
 *  `--name terraria`, and lib/game-control.ts's first serviceHint, which is
 *  what worker/game-variant.ts's wrapDockerGameService names the unit. */
const TERRARIA_CONTAINER = "terraria";
/** Container path the setupScript bind-mounts the host plugin dir at and
 *  passes to `-additionalplugins` (prisma/catalog.ts's terraria entry). */
const TERRARIA_PLUGIN_MOUNT = "/tshock/CustomPlugins";
/** Customer-facing reason for a server provisioned before the setupScript
 *  carried the mount + flag: there is genuinely nowhere TShock would load a
 *  plugin from on that server, so nothing is placed at all. */
const TERRARIA_NOT_ENABLED =
  "This server was set up before one-click Terraria plugins were available, so TShock isn't reading a plugin folder we can reach yet. Contact support to have it enabled — your world is kept.";
/** Upper bound for the whole detached install (download ≤180s, then up to
 *  two restart+boot waits of ≤270s each if it has to roll back). */
const TERRARIA_JOB_TIMEOUT_MS = 15 * 60_000;

/** Shell helpers shared by install + remove. `nx_restart_wait` restarts the
 *  unit, waits for a NEW container run (StartedAt changes), then waits for
 *  TShock's own "Server started" — checking the abort markers first, because
 *  observed live TSAPI still logs "Server started" AFTER aborting plugin
 *  init. Prints "<ok|fail|timeout> <startedAt>". */
const TERRARIA_SHELL_LIB = [
  `nx_started() { docker inspect -f '{{.State.StartedAt}}' ${TERRARIA_CONTAINER} 2>/dev/null; }`,
  `nx_runlog() { [ -n "$1" ] && docker logs --since "$1" ${TERRARIA_CONTAINER} 2>&1; }`,
  `nx_restart_wait() {`,
  `  old=$(nx_started); systemctl restart ${TERRARIA_CONTAINER} >/dev/null 2>&1`,
  `  new="$old"; i=0`,
  `  while [ $i -lt 30 ]; do new=$(nx_started); [ -n "$new" ] && [ "$new" != "$old" ] && break; sleep 1; i=$((i+1)); done`,
  `  if [ -z "$new" ] || [ "$new" = "$old" ]; then echo "timeout -"; return; fi`,
  `  i=0`,
  `  while [ $i -lt 80 ]; do`,
  `    l=$(nx_runlog "$new")`,
  `    if printf '%s\\n' "$l" | grep -q -E 'Startup aborted|Failed to load assembly|has thrown an exception during initialization'; then echo "fail $new"; return; fi`,
  `    if printf '%s\\n' "$l" | grep -q 'Server started'; then sleep 3; echo "ok $new"; return; fi`,
  `    sleep 3; i=$((i+1))`,
  `  done`,
  `  echo "timeout $new"`,
  `}`,
].join("\n");

function terrariaInstallScript(dirShell: string, file: string, url: string): string {
  return [
    `set +e`,
    TERRARIA_SHELL_LIB,
    `dir=$( ${dirShell} )`,
    `if [ -z "$dir" ]; then echo NXTP:NODIR; echo NXTP:END; exit 0; fi`,
    `f="$dir/${file}"; w=$(mktemp -d)`,
    `if ! curl -fsSL --max-time 180 -o "$w/p" '${shq(url)}'; then rm -rf "$w"; echo NXTP:DLFAIL; echo NXTP:END; exit 0; fi`,
    // Every .NET assembly is a PE file ("MZ"). Anything else — an HTML error
    // page, a zip — would just make TShock abort startup.
    `if [ "$(head -c 2 "$w/p")" != "MZ" ]; then rm -rf "$w"; echo NXTP:NOTDLL; echo NXTP:END; exit 0; fi`,
    `was=$(systemctl is-active ${TERRARIA_CONTAINER})`,
    `prev=$(nx_started)`,
    `nx_runlog "$prev" | grep -o 'Plugin .* initiated\\.' | sort -u > "$w/before"`,
    `exb=$(nx_runlog "$prev" | grep -c 'Exception')`,
    // Reinstall/update keeps the previous copy aside (".nxprev" doesn't end in
    // .dll, so TShock ignores it) so a failed update restores it, not nothing.
    `[ -f "$f" ] && cp -f "$f" "$f.nxprev"`,
    `mv -f "$w/p" "$f"; chmod 644 "$f"`,
    `set -- $(nx_restart_wait); st=$1; ts=$2; echo "NXTP:BOOT:$st"`,
    `res=installed`,
    `if [ "$st" = ok ]; then`,
    `  l=$(nx_runlog "$ts")`,
    `  new=$(printf '%s\\n' "$l" | grep -o 'Plugin .* initiated\\.' | sort -u | grep -vxF -f "$w/before" | grep .)`,
    `  exa=$(printf '%s\\n' "$l" | grep -c 'Exception')`,
    `  echo "NXTP:EXC:$exb:$exa"`,
    `  printf '%s\\n' "$new" | grep . | sed 's/^/NXTP:NEW:/'`,
    `  if [ -z "$new" ]; then res=noload; elif [ "$exa" -gt "$exb" ]; then res=errors; fi`,
    `else`,
    `  res=bootfail`,
    `  [ "$ts" != "-" ] && nx_runlog "$ts" | grep -E -m1 'Could not load file or assembly|Failed to load assembly|has thrown an exception during initialization' | sed 's/^/NXTP:WHY:/'`,
    `fi`,
    `if [ "$res" != installed ]; then`,
    `  rm -f "$f"; [ -f "$f.nxprev" ] && mv -f "$f.nxprev" "$f"`,
    `  set -- $(nx_restart_wait); echo "NXTP:ROLLBACK:$1"`,
    `else`,
    `  rm -f "$f.nxprev"`,
    `fi`,
    // Started it only to verify — leave it the way the customer had it.
    `[ "$was" != active ] && systemctl stop ${TERRARIA_CONTAINER} >/dev/null 2>&1`,
    `rm -rf "$w"`,
    `echo "NXTP:RESULT:$res"`,
    `echo NXTP:END`,
  ].join("\n");
}

function terrariaRemoveScript(dirShell: string, file: string): string {
  return [
    `set +e`,
    TERRARIA_SHELL_LIB,
    `dir=$( ${dirShell} )`,
    `if [ -n "$dir" ]; then`,
    `  rm -f "$dir/${file}" "$dir/${file}.nxprev"`,
    // A removal only takes effect on TShock's next start — restart now so the
    // panel's "removed" is true of the running server, not just of the disk.
    `  if [ "$(systemctl is-active ${TERRARIA_CONTAINER})" = active ]; then set -- $(nx_restart_wait); echo "NXTP:BOOT:$1"; fi`,
    `fi`,
    `echo NXTP:REMOVED`,
    `echo NXTP:END`,
  ].join("\n");
}

const sleepMs = (ms: number) => new Promise((r) => setTimeout(r, ms));

/**
 * Run `script` on the VM fully detached (setsid+nohup, output to a log file)
 * and poll that log over fresh short SSH sessions until it prints NXTP:END.
 * A dropped connection (seen live on a real node during this work: ECONNRESET
 * mid-command) then only costs one poll instead of killing the script halfway.
 * `tag` must be unique per attempt; re-sending the same tag never starts a
 * second copy.
 */
async function runDetached(server: SshServer, tag: string, script: string, timeoutMs: number): Promise<string> {
  const dir = "/root/.nxeon-jobs";
  const b64 = Buffer.from(script, "utf8").toString("base64");
  const start =
    `mkdir -p ${dir} && if [ -e ${dir}/${tag}.log ]; then echo NXSTARTED; else ` +
    `echo '${b64}' | base64 -d > ${dir}/${tag}.sh && : > ${dir}/${tag}.log && ` +
    `(setsid nohup sh ${dir}/${tag}.sh > ${dir}/${tag}.log 2>&1 < /dev/null &) && echo NXSTARTED; fi`;
  let started = false;
  for (let attempt = 0; attempt < 3 && !started; attempt++) {
    try {
      const r = await withSsh(server, (c) => execRemote(c, start));
      started = /NXSTARTED/.test(r.stdout);
    } catch (e) {
      if (attempt === 2) throw e;
      await sleepMs(5000);
    }
  }
  if (!started) throw new Error("could not start the plugin change on the server");

  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    await sleepMs(5000);
    try {
      const r = await withSsh(server, (c) => execRemote(c, `cat ${dir}/${tag}.log 2>/dev/null`));
      if (r.stdout.includes("NXTP:END")) {
        await withSsh(server, (c) => execRemote(c, `rm -f ${dir}/${tag}.sh ${dir}/${tag}.log`)).catch(() => {});
        return r.stdout;
      }
    } catch {
      /* transient SSH failure — keep polling until the deadline */
    }
  }
  throw new Error("timed out waiting for the server to restart with the plugin change");
}

const TERRARIA_ROLLED_BACK = "It was removed again and your server was restarted without it.";

async function installTerrariaPlugin(server: SshServer, dirShell: string, file: string, url: string): Promise<ModResult> {
  const tag = `tplugin-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  const out = await runDetached(server, tag, terrariaInstallScript(dirShell, file, url), TERRARIA_JOB_TIMEOUT_MS);
  if (out.includes("NXTP:NODIR")) return { ok: false, error: TERRARIA_NOT_ENABLED };
  if (out.includes("NXTP:DLFAIL")) return { ok: false, error: "Download failed on the server." };
  if (out.includes("NXTP:NOTDLL")) return { ok: false, error: "The download wasn't a TShock plugin (.dll) — install it by hand in Files." };

  const result = /NXTP:RESULT:(\w+)/.exec(out)?.[1];
  const rollback = /NXTP:ROLLBACK:(\w+)/.exec(out)?.[1];
  const rollbackNote =
    rollback && rollback !== "ok"
      ? " Your server didn't come back up cleanly after removing it — check Console → Logs, or contact support."
      : "";
  if (result === "installed") {
    // "Plugin QoL v1.3.3.0 (by Soofa) initiated." → "1.3.3.0"
    const version = /NXTP:NEW:Plugin .+? v(\S+) \(by /.exec(out)?.[1];
    return { ok: true, version };
  }
  if (result === "noload") {
    return { ok: false, error: `TShock didn't load it — it isn't built for this server's TShock version. ${TERRARIA_ROLLED_BACK}${rollbackNote}` };
  }
  if (result === "errors") {
    return {
      ok: false,
      error: `It loaded but threw errors while your server started (usually a TShock-version mismatch). ${TERRARIA_ROLLED_BACK}${rollbackNote}`,
    };
  }
  if (result === "bootfail") {
    const why = /NXTP:WHY:(.+)/.exec(out)?.[1]?.trim();
    const boot = /NXTP:BOOT:(\w+)/.exec(out)?.[1];
    const reason = boot === "timeout" ? "it didn't finish starting within 4 minutes" : why ? `TShock: ${why.slice(0, 200)}` : "TShock aborted startup";
    return { ok: false, error: `Your server couldn't start with it installed (${reason}). ${TERRARIA_ROLLED_BACK}${rollbackNote}` };
  }
  return { ok: false, error: "The plugin change didn't report a result — check Console → Logs." };
}

async function removeTerrariaPlugin(server: SshServer, dirShell: string, file: string): Promise<ModResult> {
  const tag = `tplugin-rm-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  const out = await runDetached(server, tag, terrariaRemoveScript(dirShell, file), TERRARIA_JOB_TIMEOUT_MS);
  return out.includes("NXTP:REMOVED") ? { ok: true } : { ok: false, error: "Couldn't confirm the plugin was removed." };
}

