411	// ===========================================================================
412	// Terraria (TShock) — place a plugin .dll, restart, PROVE it loaded, or undo.
413	//
414	// Every other file-drop family above ends at "the file is in the folder".
415	// That is not enough here, for two reasons verified against a real running
416	// `ryshe/terraria` container (TShock 6.1.0.0 / TSAPI 2.1 / Terraria 1.4.5.6,
417	// 2026-09-30 — see docs/DOCUMENTATION.md's entry of that date):
418	//
419	//  1. TShock only loads plugins at startup. A file dropped into a running
420	//     server does nothing until the next restart, so "installed" without a
421	//     restart would be a claim nothing had checked yet.
422	//  2. A plugin that fails to load or throws in Initialize() does not just
423	//     skip itself: TSAPI logs "Startup aborted due to an exception in the
424	//     Server API initialization" and stops initializing plugins — observed
425	//     live, the world still comes up and logs "Server started", so the port
426	//     answers while TShock's own protections/commands may never have been
427	//     wired up. A catalogue entry built for another TShock version (or one
428	//     that hardcodes a path this image doesn't have — also observed live)
429	//     would otherwise sit there as a time bomb for the customer's next
430	//     restart.
431	//
432	// So an install here = download → check it's a PE file → restart the game's
433	// own systemd unit → read the new run's log → INSTALLED only if TShock logged
434	// a NEW "Plugin X vY (by Z) initiated." line and nothing aborted/threw that
435	// the previous run didn't; anything else is rolled back (file removed or the
436	// previous version restored, server restarted again) and reported FAILED
437	// with TShock's own reason.
438	//
439	// WHERE the file goes: TERRARIA_PLUGIN_MOUNT, a separate host folder TShock
440	// is told to load from with TSAPI's own `-additionalplugins` flag (confirmed
441	// present in this build's TerrariaServer.dll) — never /tshock/ServerPlugins,
442	// which holds TShock's own core. lib/terraria-plugins.ts has the live test
443	// behind that choice.
444	//
445	// The whole sequence runs as ONE detached script on the VM (`runDetached`),
446	// polled over short SSH sessions, so a dropped SSH connection mid-restart
447	// can't kill it halfway between "file placed" and "verified or rolled back".
448	// ===========================================================================
449	
450	/** Customer-facing reason for a server provisioned before the setupScript
451	 *  carried the mount + flag: there is genuinely nowhere TShock would load a
452	 *  plugin from on that server, so nothing is placed at all. */
453	const TERRARIA_NOT_ENABLED =
454	  "This server was set up before one-click Terraria plugins were available, so TShock isn't reading a plugin folder we can reach yet. Contact support to have it enabled — your world is kept.";
455	/** Upper bound for the whole detached install (download ≤180s, then up to
456	 *  two restart+boot waits of ≤270s each if it has to roll back). */
457	const TERRARIA_JOB_TIMEOUT_MS = 15 * 60_000;
458	
459	/** Shell helpers shared by install + remove. `nx_restart_wait` restarts the
460	 *  unit, waits for a NEW container run (StartedAt changes), then waits for
461	 *  TShock's own "Server started" — checking the abort markers first, because
462	 *  observed live TSAPI still logs "Server started" AFTER aborting plugin
463	 *  init. Prints "<ok|fail|timeout> <startedAt>". */
464	const TERRARIA_SHELL_LIB = [
465	  `nx_started() { docker inspect -f '{{.State.StartedAt}}' ${TERRARIA_CONTAINER} 2>/dev/null; }`,
466	  `nx_runlog() { [ -n "$1" ] && docker logs --since "$1" ${TERRARIA_CONTAINER} 2>&1; }`,
467	  `nx_restart_wait() {`,
468	  `  old=$(nx_started); systemctl restart ${TERRARIA_CONTAINER} >/dev/null 2>&1`,
469	  `  new="$old"; i=0`,
470	  `  while [ $i -lt 30 ]; do new=$(nx_started); [ -n "$new" ] && [ "$new" != "$old" ] && break; sleep 1; i=$((i+1)); done`,
471	  `  if [ -z "$new" ] || [ "$new" = "$old" ]; then echo "timeout -"; return; fi`,
472	  `  i=0`,
473	  `  while [ $i -lt 80 ]; do`,
474	  `    l=$(nx_runlog "$new")`,
475	  `    if printf '%s\\n' "$l" | grep -q -E 'Startup aborted|Failed to load assembly|has thrown an exception during initialization'; then echo "fail $new"; return; fi`,
476	  `    if printf '%s\\n' "$l" | grep -q 'Server started'; then sleep 3; echo "ok $new"; return; fi`,
477	  `    sleep 3; i=$((i+1))`,
478	  `  done`,
479	  `  echo "timeout $new"`,
480	  `}`,
481	].join("\n");
482	
483	function terrariaInstallScript(dirShell: string, file: string, url: string): string {
484	  return [
485	    `set +e`,
486	    TERRARIA_SHELL_LIB,
487	    `dir=$( ${dirShell} )`,
488	    `if [ -z "$dir" ]; then echo NXTP:NODIR; echo NXTP:END; exit 0; fi`,
489	    `f="$dir/${file}"; w=$(mktemp -d)`,
490	    `if ! curl -fsSL --max-time 180 -o "$w/p" '${shq(url)}'; then rm -rf "$w"; echo NXTP:DLFAIL; echo NXTP:END; exit 0; fi`,
491	    // Every .NET assembly is a PE file ("MZ"). Anything else — an HTML error
492	    // page, a zip — would just make TShock abort startup.
493	    `if [ "$(head -c 2 "$w/p")" != "MZ" ]; then rm -rf "$w"; echo NXTP:NOTDLL; echo NXTP:END; exit 0; fi`,
494	    `was=$(systemctl is-active ${TERRARIA_CONTAINER})`,
495	    `prev=$(nx_started)`,
496	    `nx_runlog "$prev" | grep -o 'Plugin .* initiated\\.' | sort -u > "$w/before"`,
497	    `exb=$(nx_runlog "$prev" | grep -c 'Exception')`,
498	    // Reinstall/update keeps the previous copy aside (".nxprev" doesn't end in
499	    // .dll, so TShock ignores it) so a failed update restores it, not nothing.
500	    `[ -f "$f" ] && cp -f "$f" "$f.nxprev"`,
501	    `mv -f "$w/p" "$f"; chmod 644 "$f"`,
502	    `set -- $(nx_restart_wait); st=$1; ts=$2; echo "NXTP:BOOT:$st"`,
503	    `res=installed`,
504	    `if [ "$st" = ok ]; then`,
505	    `  l=$(nx_runlog "$ts")`,
506	    `  new=$(printf '%s\\n' "$l" | grep -o 'Plugin .* initiated\\.' | sort -u | grep -vxF -f "$w/before" | grep .)`,
507	    `  exa=$(printf '%s\\n' "$l" | grep -c 'Exception')`,
508	    `  echo "NXTP:EXC:$exb:$exa"`,
509	    `  printf '%s\\n' "$new" | grep . | sed 's/^/NXTP:NEW:/'`,
510	    `  if [ -z "$new" ]; then res=noload; elif [ "$exa" -gt "$exb" ]; then res=errors; fi`,
511	    `else`,
512	    `  res=bootfail`,
513	    `  [ "$ts" != "-" ] && nx_runlog "$ts" | grep -E -m1 'Could not load file or assembly|Failed to load assembly|has thrown an exception during initialization' | sed 's/^/NXTP:WHY:/'`,
514	    `fi`,
515	    `if [ "$res" != installed ]; then`,
516	    `  rm -f "$f"; [ -f "$f.nxprev" ] && mv -f "$f.nxprev" "$f"`,
517	    `  set -- $(nx_restart_wait); echo "NXTP:ROLLBACK:$1"`,
518	    `else`,
519	    `  rm -f "$f.nxprev"`,
520	    `fi`,
521	    // Started it only to verify — leave it the way the customer had it.
522	    `[ "$was" != active ] && systemctl stop ${TERRARIA_CONTAINER} >/dev/null 2>&1`,
523	    `rm -rf "$w"`,
524	    `echo "NXTP:RESULT:$res"`,
525	    `echo NXTP:END`,
526	  ].join("\n");
527	}
