529	function terrariaRemoveScript(dirShell: string, file: string): string {
530	  return [
531	    `set +e`,
532	    TERRARIA_SHELL_LIB,
533	    `dir=$( ${dirShell} )`,
534	    `if [ -n "$dir" ]; then`,
535	    `  rm -f "$dir/${file}" "$dir/${file}.nxprev"`,
536	    // A removal only takes effect on TShock's next start — restart now so the
537	    // panel's "removed" is true of the running server, not just of the disk.
538	    `  if [ "$(systemctl is-active ${TERRARIA_CONTAINER})" = active ]; then set -- $(nx_restart_wait); echo "NXTP:BOOT:$1"; fi`,
539	    `fi`,
540	    `echo NXTP:REMOVED`,
541	    `echo NXTP:END`,
542	  ].join("\n");
543	}
