545	const sleepMs = (ms: number) => new Promise((r) => setTimeout(r, ms));
546	
547	/**
548	 * Run `script` on the VM fully detached (setsid+nohup, output to a log file)
549	 * and poll that log over fresh short SSH sessions until it prints NXTP:END.
550	 * A dropped connection (seen live on a real node during this work: ECONNRESET
551	 * mid-command) then only costs one poll instead of killing the script halfway.
552	 * `tag` must be unique per attempt; re-sending the same tag never starts a
553	 * second copy.
554	 */
555	async function runDetached(server: SshServer, tag: string, script: string, timeoutMs: number): Promise<string> {
556	  const dir = "/root/.nxeon-jobs";
557	  const b64 = Buffer.from(script, "utf8").toString("base64");
558	  const start =
559	    `mkdir -p ${dir} && if [ -e ${dir}/${tag}.log ]; then echo NXSTARTED; else ` +
560	    `echo '${b64}' | base64 -d > ${dir}/${tag}.sh && : > ${dir}/${tag}.log && ` +
561	    `(setsid nohup sh ${dir}/${tag}.sh > ${dir}/${tag}.log 2>&1 < /dev/null &) && echo NXSTARTED; fi`;
562	  let started = false;
563	  for (let attempt = 0; attempt < 3 && !started; attempt++) {
564	    try {
565	      const r = await withSsh(server, (c) => execRemote(c, start));
566	      started = /NXSTARTED/.test(r.stdout);
567	    } catch (e) {
568	      if (attempt === 2) throw e;
569	      await sleepMs(5000);
570	    }
571	  }
572	  if (!started) throw new Error("could not start the plugin change on the server");
573	
574	  const deadline = Date.now() + timeoutMs;
575	  while (Date.now() < deadline) {
576	    await sleepMs(5000);
577	    try {
578	      const r = await withSsh(server, (c) => execRemote(c, `cat ${dir}/${tag}.log 2>/dev/null`));
579	      if (r.stdout.includes("NXTP:END")) {
580	        await withSsh(server, (c) => execRemote(c, `rm -f ${dir}/${tag}.sh ${dir}/${tag}.log`)).catch(() => {});
581	        return r.stdout;
582	      }
583	    } catch {
584	      /* transient SSH failure — keep polling until the deadline */
585	    }
586	  }
587	  throw new Error("timed out waiting for the server to restart with the plugin change");
588	}
