592	async function installTerrariaPlugin(server: SshServer, dirShell: string, file: string, url: string): Promise<ModResult> {
593	  const tag = `tplugin-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
594	  const out = await runDetached(server, tag, terrariaInstallScript(dirShell, file, url), TERRARIA_JOB_TIMEOUT_MS);
595	  if (out.includes("NXTP:NODIR")) return { ok: false, error: TERRARIA_NOT_ENABLED };
596	  if (out.includes("NXTP:DLFAIL")) return { ok: false, error: "Download failed on the server." };
597	  if (out.includes("NXTP:NOTDLL")) return { ok: false, error: "The download wasn't a TShock plugin (.dll) — install it by hand in Files." };
598	
599	  const result = /NXTP:RESULT:(\w+)/.exec(out)?.[1];
600	  const rollback = /NXTP:ROLLBACK:(\w+)/.exec(out)?.[1];
601	  const rollbackNote =
602	    rollback && rollback !== "ok"
603	      ? " Your server didn't come back up cleanly after removing it — check Console → Logs, or contact support."
604	      : "";
605	  if (result === "installed") {
606	    // "Plugin QoL v1.3.3.0 (by Soofa) initiated." → "1.3.3.0"
607	    const version = /NXTP:NEW:Plugin .+? v(\S+) \(by /.exec(out)?.[1];
608	    return { ok: true, version };
609	  }
610	  if (result === "noload") {
611	    return { ok: false, error: `TShock didn't load it — it isn't built for this server's TShock version. ${TERRARIA_ROLLED_BACK}${rollbackNote}` };
612	  }
613	  if (result === "errors") {
614	    return {
615	      ok: false,
616	      error: `It loaded but threw errors while your server started (usually a TShock-version mismatch). ${TERRARIA_ROLLED_BACK}${rollbackNote}`,
617	    };
618	  }
619	  if (result === "bootfail") {
620	    const why = /NXTP:WHY:(.+)/.exec(out)?.[1]?.trim();
621	    const boot = /NXTP:BOOT:(\w+)/.exec(out)?.[1];
622	    const reason = boot === "timeout" ? "it didn't finish starting within 4 minutes" : why ? `TShock: ${why.slice(0, 200)}` : "TShock aborted startup";
623	    return { ok: false, error: `Your server couldn't start with it installed (${reason}). ${TERRARIA_ROLLED_BACK}${rollbackNote}` };
624	  }
625	  return { ok: false, error: "The plugin change didn't report a result — check Console → Logs." };
626	}
