628	async function removeTerrariaPlugin(server: SshServer, dirShell: string, file: string): Promise<ModResult> {
629	  const tag = `tplugin-rm-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
630	  const out = await runDetached(server, tag, terrariaRemoveScript(dirShell, file), TERRARIA_JOB_TIMEOUT_MS);
631	  return out.includes("NXTP:REMOVED") ? { ok: true } : { ok: false, error: "Couldn't confirm the plugin was removed." };
632	}
