const shq = (s: string) => `'${s.replace(/'/g, "'\\''")}'`;

/**
 * Shell that prints the host plugin folder ONLY if the live container both
 * bind-mounts something at TERRARIA_PLUGIN_MOUNT and was started with
 * `-additionalplugins TERRARIA_PLUGIN_MOUNT` — without the flag TShock never
 * looks there, so a file placed in it would be a fake "installed". Prints
 * nothing for a server provisioned before the setupScript carried both.
 */
export function terrariaPluginDirShell(): string {
  return (
    `c=$(docker inspect ${TERRARIA_CONTAINER} --format '{{json .Config.Cmd}}' 2>/dev/null); ` +
    `d=$(docker inspect ${TERRARIA_CONTAINER} --format '{{range .Mounts}}{{if eq .Destination "${TERRARIA_PLUGIN_MOUNT}"}}{{.Source}}{{end}}{{end}}' 2>/dev/null); ` +
    `printf '%s' "$c" | grep -qF -- '"-additionalplugins","${TERRARIA_PLUGIN_MOUNT}"' && [ -n "$d" ] && [ -d "$d" ] && echo "$d"`
  );
}

/** Customer-facing reason for a server provisioned before the setupScript
 *  carried the mount + flag: there is genuinely nowhere TShock would load a
 *  plugin from on that server, so nothing is placed at all. */
export const TERRARIA_NOT_ENABLED =
  "This server was set up before one-click Terraria plugins were available, so TShock isn't reading a plugin folder we can reach yet. Contact support to have it enabled — your world is kept.";

/** Upper bound for a whole detached install: download (≤180s), then up to
 *  two restart+boot waits (≤~275s each) if it has to roll back. */
export const TERRARIA_JOB_TIMEOUT_MS = 15 * 60_000;

/** Shell helpers shared by install + remove. `nx_restart_wait` restarts the
 *  unit, waits for a NEW container run (StartedAt changes), then waits for
 *  TShock's own "Server started" — checking the abort markers FIRST, because
 *  (observed live) TSAPI still logs "Server started" after aborting plugin
 *  initialization. Prints "<ok|fail|timeout> <startedAt or ->". */
const SHELL_LIB = [
  `nx_started() { docker inspect -f '{{.State.StartedAt}}' ${TERRARIA_CONTAINER} 2>/dev/null; }`,
  `nx_runlog() { [ -n "$1" ] && [ "$1" != "-" ] && docker logs --since "$1" ${TERRARIA_CONTAINER} 2>&1; }`,
  `nx_restart_wait() {`,
  `  old=$(nx_started); systemctl restart ${TERRARIA_CONTAINER} >/dev/null 2>&1`,
  `  new="$old"; i=0`,
  `  while [ $i -lt 30 ]; do new=$(nx_started); [ -n "$new" ] && [ "$new" != "$old" ] && break; sleep 1; i=$((i+1)); done`,
  `  if [ -z "$new" ] || [ "$new" = "$old" ]; then echo "timeout -"; return; fi`,
  `  i=0`,
  `  while [ $i -lt 80 ]; do`,
  `    l=$(nx_runlog "$new")`,
  `    if printf '%s\\n' "$l" | grep -q -E 'Startup aborted|Failed to load assembly|has thrown an exception during initialization'; then echo "fail $new"; return; fi`,
  `    if printf '%s\\n' "$l" | grep -q 'Server started'; then sleep 3; echo "ok $new"; return; fi`,
  `    sleep 3; i=$((i+1))`,
  `  done`,
  `  echo "timeout $new"`,
  `}`,
].join("\n");

/**
 * The detached install script for one plugin file. Markers (one per line):
 *   NXTP:NODIR | NXTP:DLFAIL | NXTP:NOTDLL — stopped before touching anything
 *   NXTP:SAME — this exact file was already in place (nothing to restart)
 *   NXTP:BOOT:<ok|fail|timeout>  NXTP:NEW:<TShock's "Plugin … initiated." line>
 *   NXTP:WHY:<TShock's own error line>  NXTP:ROLLBACK:<ok|fail|timeout>
