411	// Terraria (TShock) — place a plugin .dll, restart, PROVE it loaded, or undo.
412	//
413	// Every other file-drop family above ends at "the file is in the folder".
414	// That is not enough here, for two reasons verified against a real running
415	// `ryshe/terraria` container (TShock 6.1.0.0 / TSAPI 2.1 / Terraria 1.4.5.6,
416	// 2026-09-30 — see docs/DOCUMENTATION.md's entry of that date):
417	//
418	//  1. TShock only loads plugins at startup. A file dropped into a running
419	//     server does nothing until the next restart, so "installed" without a
420	//     restart would be a claim nothing had checked yet.
421	//  2. A plugin that fails to load or throws in Initialize() does not just
422	//     skip itself: TSAPI logs "Startup aborted due to an exception in the
423	//     Server API initialization" and stops initializing plugins — observed
424	//     live, the world still comes up and logs "Server started", so the port
425	//     answers while TShock's own protections/commands may never have been
426	//     wired up. A catalogue entry built for another TShock version (or one
427	//     that hardcodes a path this image doesn't have — also observed live)
428	//     would otherwise sit there as a time bomb for the customer's next
429	//     restart.
430	//
431	// So an install here = download → check it's a PE file → restart the game's
432	// own systemd unit → read the new run's log → INSTALLED only if TShock logged
433	// a NEW "Plugin X vY (by Z) initiated." line and nothing aborted/threw that
434	// the previous run didn't; anything else is rolled back (file removed or the
435	// previous version restored, server restarted again) and reported FAILED
436	// with TShock's own reason.
437	//
438	// WHERE the file goes: TERRARIA_PLUGIN_MOUNT, a separate host folder TShock
439	// is told to load from with TSAPI's own `-additionalplugins` flag (confirmed
440	// present in this build's TerrariaServer.dll) — never /tshock/ServerPlugins,
441	// which holds TShock's own core. lib/terraria-plugins.ts has the live test
442	// behind that choice.
443	//
444	// The whole sequence runs as ONE detached script on the VM (`runDetached`),
445	// polled over short SSH sessions, so a dropped SSH connection mid-restart
446	// can't kill it halfway between "file placed" and "verified or rolled back".
447	// ===========================================================================
448	
449	const sleepMs = (ms: number) => new Promise((r) => setTimeout(r, ms));
450	
451	/**
452	 * Run `script` on the VM fully detached (setsid+nohup, output to a log file)
453	 * and poll that log over fresh short SSH sessions until it prints NXTP:END.
454	 * A dropped connection (seen live on a real node during this work: ECONNRESET
455	 * mid-command) then only costs one poll instead of killing the script halfway.
456	 * `tag` must be unique per attempt; re-sending the same tag never starts a
457	 * second copy.
458	 */
459	async function runDetached(server: SshServer, tag: string, script: string, timeoutMs: number): Promise<string> {
460	  const dir = "/root/.nxeon-jobs";
461	  const b64 = Buffer.from(script, "utf8").toString("base64");
462	  const start =
463	    `mkdir -p ${dir} && if [ -e ${dir}/${tag}.log ]; then echo NXSTARTED; else ` +
464	    `echo '${b64}' | base64 -d > ${dir}/${tag}.sh && : > ${dir}/${tag}.log && ` +
465	    `(setsid nohup sh ${dir}/${tag}.sh > ${dir}/${tag}.log 2>&1 < /dev/null &) && echo NXSTARTED; fi`;
466	  let started = false;
467	  for (let attempt = 0; attempt < 3 && !started; attempt++) {
468	    try {
469	      const r = await withSsh(server, (c) => execRemote(c, start));
470	      started = /NXSTARTED/.test(r.stdout);
471	    } catch (e) {
472	      if (attempt === 2) throw e;
473	      await sleepMs(5000);
474	    }
475	  }
476	  if (!started) throw new Error("could not start the plugin change on the server");
477	
478	  const deadline = Date.now() + timeoutMs;
479	  while (Date.now() < deadline) {
480	    await sleepMs(5000);
481	    try {
482	      const r = await withSsh(server, (c) => execRemote(c, `cat ${dir}/${tag}.log 2>/dev/null`));
483	      if (r.stdout.includes("NXTP:END")) {
484	        await withSsh(server, (c) => execRemote(c, `rm -f ${dir}/${tag}.sh ${dir}/${tag}.log`)).catch(() => {});
485	        return r.stdout;
486	      }
487	    } catch {
488	      /* transient SSH failure — keep polling until the deadline */
489	    }
490	  }
491	  throw new Error("timed out waiting for the server to restart with the plugin change");
492	}
493	
494	async function installTerrariaPlugin(server: SshServer, file: string, url: string): Promise<ModResult> {
495	  const tag = `tplugin-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
496	  const out = await runDetached(server, tag, terrariaInstallScript(file, url), TERRARIA_JOB_TIMEOUT_MS);
497	  return parseTerrariaInstall(out);
498	}
499	
500	async function removeTerrariaPlugin(server: SshServer, file: string): Promise<ModResult> {
501	  const tag = `tplugin-rm-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
502	  const out = await runDetached(server, tag, terrariaRemoveScript(file), TERRARIA_JOB_TIMEOUT_MS);
503	  return parseTerrariaRemove(out);
504	}
505	
506	// --- SSH transport (root@VM, password from the same source as the file manager) ---
507	
508	type ModRowFull = ModRow & { variant: string | null; appliesTo: string | null };
