import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  TERRARIA_NOT_ENABLED,
  TERRARIA_PLUGIN_HOST_DIR,
  TERRARIA_PLUGIN_MOUNT,
  TERRARIA_SETUP_SCRIPT,
  parseTerrariaInstall,
  parseTerrariaRemove,
  terrariaInstallScript,
  terrariaPluginDirShell,
  terrariaRemoveScript,
} from "../lib/terraria-plugins.ts";
import { buildGameSetupScript, dockerContainerNameFrom, dockerHostMountsFrom } from "../worker/game-variant.ts";
import { INSTALLABLE_FAMILIES, installSupport } from "../lib/mod-install-support.ts";

/**
 * One-click TShock plugins for Terraria (2026-09-30). The mechanism was
 * verified against a real provisioned container; these tests pin the parts
 * that can silently drift without one: the setupScript still carries the
 * mount + flag the installer looks for, the remote scripts still parse, and
 * each marker still maps to what the customer is told.
 */

test("setupScript mounts the plugin folder and tells TShock to load from it", () => {
  assert.match(TERRARIA_SETUP_SCRIPT, new RegExp(` -v ${TERRARIA_PLUGIN_HOST_DIR}:${TERRARIA_PLUGIN_MOUNT} `));
  assert.match(TERRARIA_SETUP_SCRIPT, new RegExp(` -additionalplugins ${TERRARIA_PLUGIN_MOUNT}$`));
  // never over TShock's own core plugin volume
  assert.doesNotMatch(TERRARIA_SETUP_SCRIPT, /:\/tshock\/ServerPlugins\b/);
  // the original boot fix must survive
  assert.match(TERRARIA_SETUP_SCRIPT, /-e WORLD_FILENAME=nxeon\.wld /);
  assert.match(TERRARIA_SETUP_SCRIPT, /-autocreate 2 -worldname Nxeon/);
});

test("the worker's wrap keeps every mount and the flag, and wipe/reinstall sees both host folders", () => {
  const wrapped = buildGameSetupScript({ osTemplate: { setupScript: TERRARIA_SETUP_SCRIPT, family: "terraria" } });
  assert.ok(wrapped);
  const create = wrapped!.split("\n")[0];
  assert.match(create, /docker create --name terraria /);
  assert.match(create, new RegExp(`-v ${TERRARIA_PLUGIN_HOST_DIR}:${TERRARIA_PLUGIN_MOUNT}`));
  assert.match(create, /-v \/opt\/terraria:\/tshock\/tshock/);
  assert.match(create, new RegExp(`ryshe/terraria:latest -autocreate 2 -worldname Nxeon -additionalplugins ${TERRARIA_PLUGIN_MOUNT}$`));
  assert.doesNotMatch(create, /--restart/);
  assert.match(wrapped!, /systemctl enable --now terraria/);
  assert.equal(dockerContainerNameFrom(TERRARIA_SETUP_SCRIPT), "terraria");
  assert.deepEqual(dockerHostMountsFrom(TERRARIA_SETUP_SCRIPT), ["/opt/terraria", TERRARIA_PLUGIN_HOST_DIR]);
});

test("install support: terraria is one-click for github TShock plugins only", () => {
  assert.ok(INSTALLABLE_FAMILIES.has("terraria"));
  assert.deepEqual(installSupport("terraria", "github"), { ok: true });
  for (const src of ["steam_workshop", "modrinth", "thunderstore"]) {
    const s = installSupport("terraria", src);
    assert.equal(s.ok, false, src);
    if (!s.ok) assert.equal(s.reason, "source");
  }
  // no other family's sources changed
  assert.deepEqual(installSupport("minecraft", "modrinth"), { ok: true });
  assert.deepEqual(installSupport("ark", "steam_workshop"), { ok: true });
  assert.equal(installSupport("cs2", "github").ok, false);
});

test("remote scripts parse under sh -n and dash -n", () => {
  const scripts = {
    install: terrariaInstallScript("nxeon-qol.dll", "https://github.com/o/r/releases/download/v1/it's.dll"),
    remove: terrariaRemoveScript("nxeon-qol.dll"),
    dir: terrariaPluginDirShell(),
  };
  for (const [name, body] of Object.entries(scripts)) {
    const file = join(tmpdir(), `terraria-plugin-${name}-${process.pid}.sh`);
    writeFileSync(file, body);
    try {
      execFileSync("sh", ["-n", file], { stdio: "pipe" });
      execFileSync("dash", ["-n", file], { stdio: "pipe" });
    } finally {
      rmSync(file, { force: true });
    }
  }
});

test("the plugin-folder probe requires BOTH the mount and the -additionalplugins flag", () => {
  const dir = terrariaPluginDirShell();
  assert.match(dir, new RegExp(`eq \\.Destination "${TERRARIA_PLUGIN_MOUNT}"`));
  assert.ok(dir.includes(`'"-additionalplugins","${TERRARIA_PLUGIN_MOUNT}"'`));
});

test("markers → outcome", () => {
  assert.deepEqual(parseTerrariaInstall("NXTP:NODIR\nNXTP:END\n"), { ok: false, error: TERRARIA_NOT_ENABLED });
  assert.equal(parseTerrariaInstall("NXTP:DLFAIL\nNXTP:END").ok, false);
  assert.equal(parseTerrariaInstall("NXTP:NOTDLL\nNXTP:END").ok, false);
  assert.deepEqual(
    parseTerrariaInstall(
      "NXTP:BOOT:ok\nNXTP:NEW:Plugin ComfyEconomy v1.5.7 (by Soofa) initiated.\nNXTP:RESULT:installed\nNXTP:END\n"
    ),
    { ok: true, version: "1.5.7" }
  );
  assert.deepEqual(parseTerrariaInstall("NXTP:SAME\nNXTP:RESULT:same\nNXTP:END"), { ok: true });

  const noload = parseTerrariaInstall("NXTP:BOOT:ok\nNXTP:ROLLBACK:ok\nNXTP:RESULT:noload\nNXTP:END");
  assert.equal(noload.ok, false);
  assert.match(noload.error!, /isn't built for this server's TShock version/);
  assert.doesNotMatch(noload.error!, /didn't come back up/);

  const boot = parseTerrariaInstall(
    "NXTP:BOOT:fail\nNXTP:WHY: ---> System.TypeLoadException: Could not load type 'TShockAPI.DB.IQueryBuilder'\nNXTP:ROLLBACK:ok\nNXTP:RESULT:bootfail\nNXTP:END"
  );
  assert.equal(boot.ok, false);
  assert.match(boot.error!, /IQueryBuilder/);
  assert.match(boot.error!, /removed again/);

  const stuck = parseTerrariaInstall("NXTP:BOOT:fail\nNXTP:ROLLBACK:timeout\nNXTP:RESULT:bootfail\nNXTP:END");
  assert.match(stuck.error!, /didn't come back up cleanly/);

  const errs = parseTerrariaInstall(
    'NXTP:BOOT:ok\nNXTP:NEW:Plugin PerPlayerLoot v2.0 (by Codian) initiated.\nNXTP:WHY:[Server API] Warning Plugin "PerPlayerLoot" has had an unhandled exception thrown by one of its GamePostInitialize handlers:\nNXTP:ROLLBACK:ok\nNXTP:RESULT:errors\nNXTP:END'
  );
  assert.equal(errs.ok, false);
  assert.match(errs.error!, /PerPlayerLoot/);

  assert.equal(parseTerrariaInstall("NXTP:END").ok, false);
  assert.deepEqual(parseTerrariaRemove("NXTP:BOOT:ok\nNXTP:REMOVED\nNXTP:END"), { ok: true });
  assert.equal(parseTerrariaRemove("").ok, false);
});

