input.content:
/**
 * Drive the REAL worker code (worktree's worker/game-mods.ts gameModSync, the
 * exact GAME_MOD_SYNC handler) against the THROWAWAY test server only.
 * No Job row is created, so the live prod worker never sees any of this.
 *
 *   phase=install  : create hidden (active:false) test GameMod rows + INSTALLING ServerMods, run gameModSync
 *   phase=remove   : flip the good one to REMOVING, run gameModSync
 *   phase=cleanup  : delete every test ServerMod/GameMod/Notification row this created
 */
import { assertDbTarget } from "/root/nxeon-worktrees/terraria-mods/scripts/db-target-guard";
assertDbTarget("tmods-worker-test.ts");
import { db } from "/root/nxeon-worktrees/terraria-mods/lib/db";
import { gameModSync } from "/root/nxeon-worktrees/terraria-mods/worker/game-mods";

const SERVER_ID = "cmund1re30002hlhzrosxztry";
const TEST_MODS = [
  // known-good on TShock 6.1 (pass 1 + pass 2 on the real container)
  { slug: "zz-nxtest-comfyeconomy", name: "ComfyEconomy (NXTEST)", sourceId: "LiteralSoofa/ComfyEconomy" },
  // known-bad: built against TShock 5's DB API → TypeLoadException aborts startup; must be rolled back
  { slug: "zz-nxtest-gravebags", name: "Gravebags (NXTEST)", sourceId: "pcider/Gravebags" },
];

async function main() {
  const phase = process.argv[2];
  const server = await db.server.findUniqueOrThrow({ where: { id: SERVER_ID } });
  if (server.hostname !== "tmods-test-29d892") throw new Error("not the test server");

  if (phase === "install") {
    for (const m of TEST_MODS) {
      const gm = await db.gameMod.upsert({
        where: { gameFamily_slug: { gameFamily: "terraria", slug: m.slug } },
        update: {},
        create: {
          gameFamily: "terraria", slug: m.slug, name: m.name, category: "Test", source: "github",
          sourceId: m.sourceId, url: `https://github.com/${m.sourceId}`, active: false,
          description: "INTERNAL TEST ROW — terraria mod-install verification, deleted after",
        },
      });
      await db.serverMod.upsert({
        where: { serverId_modId: { serverId: SERVER_ID, modId: gm.id } },
        update: { status: "INSTALLING", error: null },
        create: { serverId: SERVER_ID, modId: gm.id, status: "INSTALLING" },
      });
    }
  } else if (phase === "remove") {
    const gm = await db.gameMod.findUniqueOrThrow({ where: { gameFamily_slug: { gameFamily: "terraria", slug: TEST_MODS[0].slug } } });
    await db.serverMod.update({ where: { serverId_modId: { serverId: SERVER_ID, modId: gm.id } }, data: { status: "REMOVING" } });
  } else if (phase === "cleanup") {
    const gms = await db.gameMod.findMany({ where: { gameFamily: "terraria", slug: { in: TEST_MODS.map((m) => m.slug) } } });
    const sm = await db.serverMod.deleteMany({ where: { modId: { in: gms.map((g) => g.id) } } });
    const g = await db.gameMod.deleteMany({ where: { id: { in: gms.map((g) => g.id) } } });
    const n = await db.notification.deleteMany({ where: { userId: server.userId, href: `/dashboard/servers/${SERVER_ID}?tab=mods` } });
    console.log(`cleanup: serverMods=${sm.count} gameMods=${g.count} notifications=${n.count}`);
    return;
  } else {
    throw new Error("phase = install | remove | cleanup");
  }

  const t0 = Date.now();
  console.log(`[${new Date().toISOString()}] gameModSync(${SERVER_ID}) phase=${phase} ENABLE_REAL_GAMEMODS=${process.env.ENABLE_REAL_GAMEMODS} NXEON_SANDBOX=${process.env.NXEON_SANDBOX ?? "(unset)"}`);
  await gameModSync({ id: "local-test-no-job-row", serverId: SERVER_ID } as any);
  console.log(`[${new Date().toISOString()}] gameModSync returned after ${Math.round((Date.now() - t0) / 1000)}s`);

  const rows = await db.serverMod.findMany({ where: { serverId: SERVER_ID }, include: { mod: { select: { slug: true } } } });
  for (const r of rows) console.log(`ServerMod ${r.mod.slug}: status=${r.status} version=${r.version ?? "-"} error=${r.error ?? "-"}`);
  const notes = await db.notification.findMany({ where: { userId: server.userId }, orderBy: { createdAt: "desc" }, take: 1 });
  for (const n of notes) console.log(`Notification: "${n.title}" — ${n.body}`);
}
main().then(() => db.$disconnect()).catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });

