/**
 * Terraria plugin rollout (2026-09-30) — the DATA half of one-click TShock
 * plugins. Three steps, one script, dry run by default:
 *
 *   1. OsTemplate `terraria`: set `setupScript` to lib/terraria-plugins.ts's
 *      TERRARIA_SETUP_SCRIPT (the plugin mount + `-additionalplugins` flag +
 *      the /tshock/tshock data alias). Only NEW orders and Wipe & reinstall
 *      pick this up — existing servers keep the container they were created
 *      with; see "EXISTING SERVERS" below. Targeted at this one row on
 *      purpose: `prisma/catalog.ts` upserts EVERY template, and nobody has
 *      checked that production's other rows still match that file.
 *   2. Retire the wrong-platform catalogue: every terraria GameMod that is not
 *      `source: "github"` — in practice the 1000 `steam_workshop` rows
 *      scripts/import-steamworkshop-catalog.ts imported under tModLoader's
 *      appid 1281930. Nxeon's Terraria servers run TShock (no tModLoader), so
 *      none of them could ever load. Rows with nothing pointing at them are
 *      DELETED; a row some ServerMod or ModRating still references is only
 *      deactivated (active=false), so no customer's install record or review
 *      disappears.
 *   3. Upsert PLUGINS below — real TShock plugins, each one downloaded from
 *      its author's own GitHub release and test-loaded on a real, freshly
 *      provisioned Nxeon Terraria server (TShock 6.1.0.0 / Terraria 1.4.5.6)
 *      through the production install script (lib/terraria-plugins.ts), with
 *      TShock logging it "initiated" and no startup error. Everything below
 *      is copied from the GitHub API/release as of 2026-09-30, not written
 *      by hand, except `category` (an editorial grouping).
 *
 * WHAT WAS TESTED AND LEFT OUT (same real container, same script), so nobody
 * re-adds them without re-testing: see LEFT_OUT at the bottom.
 *
 * LICENSES follow scripts/import-github-catalog.ts's policy: a repo without a
 * confirmed-permissive license is still listed, link-out-only — the worker
 * always downloads from the author's own release, Nxeon never mirrors the
 * file — with `upstreamNote` saying so.
 *
 * NEWER RELEASES: the worker installs each repo's LATEST release at install
 * time (worker/game-mods.ts resolveUrl), not the tag tested here. A future
 * release built for a different TShock is caught by the installer itself
 * (restart → verify → roll back, customer told why), so a stale row fails
 * safe — but re-run the load test before trusting a changed `testedTag`.
 *
 * EXISTING SERVERS: servers created before step 1 have no plugin mount. The
 * worker detects that from the live container and tells the customer
 * (TERRARIA_NOT_ENABLED) instead of placing a file TShock would never read.
 * Enabling them means recreating their container with the new flags — an
 * owner decision per server, not something this script does.
 *
 *   Dry run:  NXEON_DB_TARGET=nxeon_staging DATABASE_URL=… npx tsx scripts/seed-terraria-tshock-plugins.ts
 *   Apply:    … --apply
 */
import { assertDbTarget } from "./db-target-guard";
assertDbTarget("seed-terraria-tshock-plugins.ts");

import { db } from "../lib/db";
import { TERRARIA_SETUP_SCRIPT } from "../lib/terraria-plugins";

type Plugin = {
  slug: string;
  name: string;
  /** GitHub owner/repo — worker/game-mods.ts resolves its latest release. */
  repo: string;
  category: string;
  /** Repo description as GitHub reports it. */
  description: string | null;
  /** GitHub's SPDX id, or null when the repo has no license file. */
  license: string | null;
  stars: number;
  owner: string;
  ownerAvatar: string;
  pushedAt: string;
  /** Release + asset that was actually test-loaded, and its real size. */
  testedTag: string;
  testedAsset: string;
  fileBytes: number;
  /** TShock's own line from that test boot. */
  loadedAs: string;
};

const PERMISSIVE = new Set(["MIT", "MIT-0", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "Unlicense", "ISC", "GPL-2.0", "GPL-3.0"]);

// PLUGINS_START
const PLUGINS: Plugin[] = [];
// PLUGINS_END

async function main() {
  const apply = process.argv.includes("--apply");
  console.log(`[seed-terraria-tshock-plugins] ${apply ? "APPLY (writing)" : "DRY RUN (no writes)"}`);

  // ── 1. OsTemplate ──────────────────────────────────────────────────────
  const tpl = await db.osTemplate.findUnique({ where: { slug: "terraria" }, select: { id: true, setupScript: true } });
  if (!tpl) throw new Error("no `terraria` OsTemplate row — nothing to update");
  const tplCurrent = tpl.setupScript === TERRARIA_SETUP_SCRIPT;
  console.log(`\n[1] OsTemplate terraria: setupScript ${tplCurrent ? "already current" : "will be replaced with TERRARIA_SETUP_SCRIPT"}`);
  if (!tplCurrent && apply) {
    await db.osTemplate.update({ where: { id: tpl.id }, data: { setupScript: TERRARIA_SETUP_SCRIPT } });
    console.log("    updated.");
  }

  // ── 2. Retire non-TShock rows ──────────────────────────────────────────
  const stale = await db.gameMod.findMany({
    where: { gameFamily: "terraria", source: { not: "github" } },
    select: { id: true, source: true, _count: { select: { installs: true, ratings: true } } },
  });
  const referenced = stale.filter((r) => r._count.installs > 0 || r._count.ratings > 0);
  const deletable = stale.filter((r) => r._count.installs === 0 && r._count.ratings === 0);
  const bySource = stale.reduce<Record<string, number>>((m, r) => ((m[r.source] = (m[r.source] ?? 0) + 1), m), {});
  console.log(`\n[2] non-github terraria rows: ${stale.length} ${JSON.stringify(bySource)}`);
  console.log(`    delete (nothing references them): ${deletable.length}`);
  console.log(`    deactivate only (a ServerMod/ModRating references them): ${referenced.length}`);
  if (apply) {
    for (let i = 0; i < deletable.length; i += 500) {
      const ids = deletable.slice(i, i + 500).map((r) => r.id);
      await db.gameMod.deleteMany({ where: { id: { in: ids } } });
    }
    if (referenced.length) {
      await db.gameMod.updateMany({ where: { id: { in: referenced.map((r) => r.id) } }, data: { active: false } });
    }
    console.log("    done.");
  }

  // ── 3. Upsert real TShock plugins ──────────────────────────────────────
  console.log(`\n[3] TShock plugins: ${PLUGINS.length}`);
  let created = 0;
  let updated = 0;
  for (const p of PLUGINS) {
    const permissive = !!p.license && PERMISSIVE.has(p.license);
    const data = {
      name: p.name,
      category: p.category,
      source: "github",
      sourceId: p.repo,
      url: `https://github.com/${p.repo}`,
      description: p.description,
      iconUrl: p.ownerAvatar,
      authorName: p.owner,
      authorAvatarUrl: p.ownerAvatar,
      popularity: Math.min(p.stars, 999),
      license: p.license,
      loaders: ["tshock"],
      serverSide: "required",
      fileBytes: p.fileBytes,
      impact: "light",
      verifiedAt: new Date(),
      upstreamOk: true,
      upstreamNote: permissive
        ? null
        : `License not confirmed permissive (GitHub reports "${p.license ?? "no license"}") — installed from the author's own release, not mirrored; verify before treating as redistribution-safe.`,
      upstreamUpdatedAt: new Date(p.pushedAt),
      active: true,
    };
    const existing = await db.gameMod.findUnique({
      where: { gameFamily_slug: { gameFamily: "terraria", slug: p.slug } },
      select: { id: true },
    });
    console.log(`    ${existing ? "update" : "create"} ${p.slug.padEnd(28)} ${p.repo} (${p.license ?? "no license"}) — tested ${p.testedTag}: "${p.loadedAs}"`);
    if (!apply) {
      existing ? updated++ : created++;
      continue;
    }
    if (existing) {
      await db.gameMod.update({ where: { id: existing.id }, data });
      updated++;
    } else {
      await db.gameMod.create({ data: { gameFamily: "terraria", slug: p.slug, ...data } });
      created++;
    }
  }

  const live = await db.gameMod.count({ where: { gameFamily: "terraria", active: true, upstreamOk: true } });
  console.log(`\nSUMMARY (${apply ? "APPLIED" : "DRY RUN — nothing written"}): template ${tplCurrent ? "unchanged" : apply ? "updated" : "would update"}; ` +
    `retired ${stale.length} (${deletable.length} delete / ${referenced.length} deactivate); plugins created ${created}, updated ${updated}; ` +
    `terraria rows active in the catalogue now: ${live}`);
}

main()
  .then(() => db.$disconnect())
  .catch(async (e) => {
    console.error(e);
    await db.$disconnect();
    process.exit(1);
  });

