+// ===========================================================================
+// Terraria (TShock) — place a plugin .dll, restart, PROVE it loaded, or undo.
+//
+// Every other file-drop family above ends at "the file is in the folder".
+// That is not enough here, for two reasons verified against a real running
+// `ryshe/terraria` container (TShock 6.1.0.0 / TSAPI 2.1 / Terraria 1.4.5.6,
+// 2026-09-30 — see docs/DOCUMENTATION.md's entry of that date):
+//
+//  1. TShock only loads plugins at startup. A file dropped into a running
+//     server does nothing until the next restart, so "installed" without a
+//     restart would be a claim nothing had checked yet.
+//  2. A plugin that fails to load or throws in Initialize() does not just
+//     skip itself: TSAPI logs "Startup aborted due to an exception in the
+//     Server API initialization" and stops initializing plugins — observed
+//     live, the world still comes up and logs "Server started", so the port
+//     answers while TShock's own protections/commands may never have been
+//     wired up. A catalogue entry built for another TShock version (or one
+//     that hardcodes a path this image doesn't have — also observed live)
+//     would otherwise sit there as a time bomb for the customer's next
+//     restart.
+//
+// So an install here = download → check it's a PE file → restart the game's
+// own systemd unit → read the new run's log → INSTALLED only if TShock logged
+// a NEW "Plugin X vY (by Z) initiated." line, nothing aborted startup, and
+// TSAPI reported no unhandled exception from that same plugin; anything else
+// is rolled back (file removed or the previous version restored, server
+// restarted again) and reported FAILED with TShock's own reason. The scripts
+// and the marker parsing live in lib/terraria-plugins.ts (pure, unit-tested);
+// this file only ships them to the VM and waits.
+//
+// WHERE the file goes: TERRARIA_PLUGIN_MOUNT, a separate host folder TShock
+// is told to load from with TSAPI's own `-additionalplugins` flag (confirmed
+// present in this build's TerrariaServer.dll) — never /tshock/ServerPlugins,
+// which holds TShock's own core. lib/terraria-plugins.ts has the live test
+// behind that choice.
+//
+// The whole sequence runs as ONE detached script on the VM (`runDetached`),
+// polled over short SSH sessions, so a dropped SSH connection mid-restart
+// can't kill it halfway between "file placed" and "verified or rolled back".
+// ===========================================================================
+
+const sleepMs = (ms: number) => new Promise((r) => setTimeout(r, ms));
+
+/**
+ * Run `script` on the VM fully detached (setsid+nohup, output to a log file)
+ * and poll that log over fresh short SSH sessions until it prints NXTP:END.
+ * A dropped connection (seen live on a real node during this work: ECONNRESET
+ * mid-command) then only costs one poll instead of killing the script halfway.
+ * `tag` must be unique per attempt; re-sending the same tag never starts a
+ * second copy.
+ */
+async function runDetached(server: SshServer, tag: string, script: string, timeoutMs: number): Promise<string> {
+  const dir = "/root/.nxeon-jobs";
+  const b64 = Buffer.from(script, "utf8").toString("base64");
+  const start =
+    `mkdir -p ${dir} && if [ -e ${dir}/${tag}.log ]; then echo NXSTARTED; else ` +
+    `echo '${b64}' | base64 -d > ${dir}/${tag}.sh && : > ${dir}/${tag}.log && ` +
+    `(setsid nohup sh ${dir}/${tag}.sh > ${dir}/${tag}.log 2>&1 < /dev/null &) && echo NXSTARTED; fi`;
+  // Five tries over ~50s: during this work a real node answered a VM's SSH
+  // port from a DIFFERENT host in bursts of tens of seconds (auth rejected,
+  // nothing run). Safe to repeat — the tag guard above makes a start that
+  // succeeded but lost its reply a no-op the second time.
+  let started = false;
+  for (let attempt = 0; attempt < 5 && !started; attempt++) {
+    try {
+      const r = await withSsh(server, (c) => execRemote(c, start));
+      started = /NXSTARTED/.test(r.stdout);
+    } catch (e) {
+      if (attempt === 4) throw e;
+      await sleepMs(5000 * (attempt + 1));
+    }
+  }
+  if (!started) throw new Error("could not start the plugin change on the server");
+
+  const deadline = Date.now() + timeoutMs;
+  while (Date.now() < deadline) {
+    await sleepMs(5000);
+    try {
+      const r = await withSsh(server, (c) => execRemote(c, `cat ${dir}/${tag}.log 2>/dev/null`));
+      if (r.stdout.includes("NXTP:END")) {
+        await withSsh(server, (c) => execRemote(c, `rm -f ${dir}/${tag}.sh ${dir}/${tag}.log`)).catch(() => {});
+        return r.stdout;
+      }
+    } catch {
+      /* transient SSH failure — keep polling until the deadline */
+    }
+  }
+  throw new Error("timed out waiting for the server to restart with the plugin change");
+}
